#!/usr/bin/env node

import {
  existsSync,
  cpSync,
  readFileSync,
  writeFileSync,
  unlinkSync
} from 'node:fs';
import { resolve, join, dirname, basename } from 'node:path';
import { execSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const PKG_ROOT = resolve(__dirname, '..');

const VALID_SHELLS = [
  'platform',
  'salesforce-opportunity',
  'salesforce-drilldown'
];
const DEFAULT_SHELL = 'platform';

function usage() {
  console.log(`
Usage:
  npx @tackle-io/design-system create prototype --name <name> [--shell <shell>] [--local <path>]

Options:
  --name   Project directory name (required)
  --shell  Application shell: platform | salesforce-opportunity | salesforce-drilldown (default: platform)
  --local  Path to a local .tgz tarball of @tackle-io/design-system to use instead of the registry
`);
  process.exit(1);
}

function parseArgs(argv) {
  const args = argv.slice(2);

  if (args[0] !== 'create' || args[1] !== 'prototype') {
    console.error('Error: unknown command. Expected "create prototype".');
    usage();
  }

  const opts = { name: '', shell: DEFAULT_SHELL, local: '' };
  let i = 2;
  while (i < args.length) {
    if (args[i] === '--name' && args[i + 1]) {
      opts.name = args[i + 1];
      i += 2;
    } else if (args[i] === '--shell' && args[i + 1]) {
      opts.shell = args[i + 1];
      i += 2;
    } else if (args[i] === '--local' && args[i + 1]) {
      opts.local = resolve(args[i + 1]);
      i += 2;
    } else {
      console.error(`Error: unknown option "${args[i]}"`);
      usage();
    }
  }

  if (!opts.name) {
    console.error('Error: --name is required.');
    usage();
  }

  if (!VALID_SHELLS.includes(opts.shell)) {
    opts.shell = DEFAULT_SHELL;
  }

  return opts;
}

function scaffoldProject({ name, shell, local }) {
  const dest = resolve(process.cwd(), name);

  if (existsSync(dest)) {
    console.error(`Error: directory "${name}" already exists.`);
    process.exit(1);
  }

  const templateDir = join(PKG_ROOT, 'template');
  const shellOverlayDir = join(PKG_ROOT, 'templates', shell);

  console.log(`\nScaffolding ${name} with ${shell} shell...`);

  cpSync(templateDir, dest, { recursive: true });
  cpSync(shellOverlayDir, dest, { recursive: true, force: true });

  const ownPkg = JSON.parse(
    readFileSync(join(PKG_ROOT, 'package.json'), 'utf8')
  );
  const dsVersion = ownPkg.version;

  let dsDepValue = dsVersion;
  if (local) {
    if (!existsSync(local)) {
      console.error(`Error: local tarball not found at "${local}"`);
      process.exit(1);
    }
    const tgzName = basename(local);
    cpSync(local, join(dest, tgzName));
    dsDepValue = `file:./${tgzName}`;
    console.log(`Using local tarball: ${tgzName}`);
  }

  const pkgTmplPath = join(dest, 'package.json.tmpl');
  let pkgContent = readFileSync(pkgTmplPath, 'utf8');
  pkgContent = pkgContent
    .replace(/\{\{name\}\}/g, name)
    .replace(/\{\{ds-version\}\}/g, dsDepValue)
    .replace(/\{\{shell\}\}/g, shell);
  writeFileSync(join(dest, 'package.json'), pkgContent);

  unlinkSync(pkgTmplPath);

  console.log('Installing dependencies...\n');
  execSync('npm install', { cwd: dest, stdio: 'inherit' });

  installAgentSkills({ dest });

  console.log(`
Done! Your prototype is ready at ./${name}

  cd ${name}
  npm run dev
`);
}

function installAgentSkills({ dest }) {
  console.log('\nWiring agent skills into AGENTS.md...');

  const agentsTemplate = join(PKG_ROOT, 'templates', 'AGENTS.md');
  const agentsDest = join(dest, 'AGENTS.md');

  if (!existsSync(agentsTemplate)) {
    console.warn(
      `\nWARNING: templates/AGENTS.md missing from the design-system package — skipping agent skills wiring. Skills are still installed in node_modules/@tackle-io/design-system/skills/, but no AGENTS.md was written.`
    );
    return;
  }

  cpSync(agentsTemplate, agentsDest);

  let intentOk = true;
  try {
    execSync('npx --yes @tanstack/intent install --map', {
      cwd: dest,
      stdio: 'inherit'
    });
  } catch (err) {
    intentOk = false;
  }

  if (!intentOk) {
    console.error(`
================================================================================
  AGENT SKILLS WERE NOT WIRED INTO AGENTS.md
  ------------------------------------------------------------------------------
  The Tackle skills are present in node_modules/@tackle-io/design-system/skills/
  and AGENTS.md has the static baseline content, but the explicit skill-to-task
  mappings could not be written by @tanstack/intent.

  Recover with one command from this prototype directory:

      npx @tanstack/intent install --map

  Until you do, your AI agent may not know about the Tackle skills for this
  project unless you force-load them with /tackle-design-system, etc.
================================================================================
`);
    return;
  }

  let skills = [];
  try {
    const json = execSync('npx --yes @tanstack/intent list --json', {
      cwd: dest,
      encoding: 'utf8'
    });
    const parsed = JSON.parse(json);
    skills = (parsed.packages || []).flatMap((p) =>
      (p.skills || []).map((s) => ({
        pkg: p.name,
        name: s.name
      }))
    );
  } catch {
    skills = [];
  }

  console.log(
    '\n--------------------------------------------------------------'
  );
  console.log('Agent skills installed for this prototype');
  console.log('--------------------------------------------------------------');
  if (skills.length === 0) {
    console.log('(Could not enumerate skills via `intent list --json`.)');
    console.log(
      'Run `npx @tanstack/intent list` from this directory to inspect.'
    );
  } else {
    for (const s of skills) {
      console.log(`  - ${s.pkg}#${s.name}`);
    }
  }
  console.log(`
  AGENTS.md has been written to your prototype root with both the static
  baseline content and the @tanstack/intent managed mappings.

  Your agent now knows the Tackle design system, content style, and
  accessibility conventions for this prototype.

  If your agent's output ever stops following Tackle conventions, force-load
  the relevant skill in chat:
      /tackle-design-system
      /tackle-content-style
      /tackle-accessibility
--------------------------------------------------------------`);
}

const opts = parseArgs(process.argv);
scaffoldProject(opts);
